    {
      "segment_index": 2,
      "name": "status_quo_description",
      "segment_title": "সংসার ও সরল জীবনযাত্রা",
      "segment_seed": "তৎকালীন বাংলার সাধারণ মানুষের জীবন ছিল অত্যন্ত সাদাসিধে। দারিদ্র্য থাকলেও সেখানে ছিল প্রাণের টান। লোক-উৎসব আর কীর্তনের আসরে সাধারণ মানুষের ভক্তিপূর্ণ সহাবস্থানের এক নিখুঁত ছবি।"
    },
    {
      "segment_index": 3,
      "name": "character_debut",
      "segment_title": "চঞ্চল বালক থেকে ভাবাতুর কিশোর",
      "segment_seed": "গ্রামের ধুলোবালিতে খেলে বেড়ানো এক কিশোর, যার চোখে সবসময় এক গভীর রহস্যের ছায়া। সংসারের কাজে মন নেই, বরং সে খুঁজে ফেরে বাতাসের বাঁশি আর উদাসী বাউলের একতারা।"
